window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-a16617a477a5b84a"]={"versions": [{"id": "FIG-a16617a477a5b84a", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Aktivitäts- und Rollendiagramm der AUTOSAR-Methodik (SPEM-basiertes Methodik-Muster aus <code>AUTOSAR_TR_Methodology</code>). Dargestellt ist der Kontext des Systementwurfs mit dem Arbeitsschritt zur Definition des PDU-Gateways (<code>Define PDU Gateway</code>) und dessen Anbindung an den ausführenden Entwickler sowie das betroffene Arbeitsergebnis.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Rolle</strong>: <code>System Engineer</code> (Kardinalität <code>1</code>), verantwortlich für die Systemkonfiguration und Gateway-Definition.\n</li><li><strong>Aktivität / Task</strong>: <code>Define PDU Gateway</code> (Kardinalität <code>1</code>), dargestellt als Prozessschritt/Aktivitätensymbol.\n</li><li><strong>Artefakt / Work Product</strong>: Unbeschriftetes Dokumenten-Symbol (System Configuration Description / System Description bzw. PDU Gateway Routing Definition).\n</li><li><strong>Beziehungen &amp; Stereotypen</strong>:\n<ul class=\"fig-list\"><li><code>«performs»</code>: Gerichtete Kante von <code>System Engineer</code> (Kardinalität <code>1</code>) auf die Aktivität <code>Define PDU Gateway</code>.\n</li><li><code>«inoutput»</code>: Bidirektional bzw. mit Pfeilspitzen an beiden Enden versehene Verbindungskante zwischen <code>Define PDU Gateway</code> (Kardinalität <code>1</code>) und dem Dokumenten-Artefakt (Kardinalität <code>1</code>), was den lesenden wie schreibenden Zugriff (Modifikation/Verfeinerung) kennzeichnet.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der <code>System Engineer</code> führt den methodischen Schritt <code>Define PDU Gateway</code> aus. Im Rahmen dieser Aktivität wird die bestehende Systembeschreibung bzw. Konfiguration eingelesen (<code>in</code>), um Routing-Beziehungen zwischen PDUs (z. B. signal- oder PDU-basiertes Gatewaying zwischen verschiedenen Bussystemen) zu definieren bzw. zu ergänzen, und das aktualisierte Artefakt wird wieder zurückgeschrieben (<code>output</code>). Beide Richtungen sind durch den Stereotyp <code>«inoutput»</code> zusammengefasst.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Definition von PDU-Gateways ist ein wesentlicher Schritt im Systemdesign von Multi-Bus-Fahrzeugnetzwerken. Entwickler und Systemingenieure müssen sicherstellen, dass Quell- und Ziel-PDUs, Routing-Tabellen sowie ggf. Signalabbildungen konsistent im System Description ARXML definiert sind. Das Artefakt fungiert als direkte Eingangs- und Ausgangsbasis für nachgelagerte ECU-Extraktions- und BSW-Konfigurationsschritte (insbesondere PduR und Com).</p>"}, {"id": "FIG-63a2147686d867e9", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Aktivitäts- und Rollendiagramm der AUTOSAR-Methodik (SPEM-basiertes Methodik-Muster aus <code>AUTOSAR_TR_Methodology</code>). Dargestellt ist der Kontext des Systementwurfs mit dem Arbeitsschritt zur Definition des PDU-Gateways (<code>Define PDU Gateway</code>) und dessen Anbindung an den ausführenden Entwickler sowie das betroffene Arbeitsergebnis.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Rolle</strong>: <code>System Engineer</code> (Kardinalität <code>1</code>), verantwortlich für die Systemkonfiguration und Gateway-Definition.\n</li><li><strong>Aktivität / Task</strong>: <code>Define PDU Gateway</code> (Kardinalität <code>1</code>), dargestellt als Prozessschritt/Aktivitätensymbol.\n</li><li><strong>Artefakt / Work Product</strong>: Unbeschriftetes Dokumenten-Symbol (System Configuration Description / System Description bzw. PDU Gateway Routing Definition).\n</li><li><strong>Beziehungen &amp; Stereotypen</strong>:\n<ul class=\"fig-list\"><li><code>«performs»</code>: Gerichtete Kante von <code>System Engineer</code> (Kardinalität <code>1</code>) auf die Aktivität <code>Define PDU Gateway</code>.\n</li><li><code>«inoutput»</code>: Bidirektional bzw. mit Pfeilspitzen an beiden Enden versehene Verbindungskante zwischen <code>Define PDU Gateway</code> (Kardinalität <code>1</code>) und dem Dokumenten-Artefakt (Kardinalität <code>1</code>), was den lesenden wie schreibenden Zugriff (Modifikation/Verfeinerung) kennzeichnet.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der <code>System Engineer</code> führt den methodischen Schritt <code>Define PDU Gateway</code> aus. Im Rahmen dieser Aktivität wird die bestehende Systembeschreibung bzw. Konfiguration eingelesen (<code>in</code>), um Routing-Beziehungen zwischen PDUs (z. B. signal- oder PDU-basiertes Gatewaying zwischen verschiedenen Bussystemen) zu definieren bzw. zu ergänzen, und das aktualisierte Artefakt wird wieder zurückgeschrieben (<code>output</code>). Beide Richtungen sind durch den Stereotyp <code>«inoutput»</code> zusammengefasst.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Definition von PDU-Gateways ist ein wesentlicher Schritt im Systemdesign von Multi-Bus-Fahrzeugnetzwerken. Entwickler und Systemingenieure müssen sicherstellen, dass Quell- und Ziel-PDUs, Routing-Tabellen sowie ggf. Signalabbildungen konsistent im System Description ARXML definiert sind. Das Artefakt fungiert als direkte Eingangs- und Ausgangsbasis für nachgelagerte ECU-Extraktions- und BSW-Konfigurationsschritte (insbesondere PduR und Com).</p>"}], "trans": [{"from": "FIG-a16617a477a5b84a", "to": "FIG-63a2147686d867e9", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
